-- Hands the A15Q_C1 refreeze confirmation packet (manifest + exact bytes of the 11 bundle files) to a SEPARATE GPT Native chat
-- as an operational event (HANDOFF_DEEP_CONTEXT). Data only: no checkpoint, spec or assertion changes. A15Q_C1 stays PENDING.
-- Tier: OWNER_APPROVED_GPT_NATIVE_IN_CHAT_EQUIVALENT (not provider-attested, not an independent review).
BEGIN;
DO $a15q_c1_handoff$
DECLARE
 v_exec constant text := 'ANALYSIS_A15Q_C1_REFREEZE_CONFIRMATION_HANDOFF_V1';
 v_sha constant text := '2bed03d21de741c9dfe8c15ed4bcb9197f5e4b5b4e5586cbc1f3807ace94baaf';
 v_pkt jsonb := $a15pkt${"checkpoint": "A15Q_C1", "checks": [{"code": "BUNDLE_BYTES_MATCH_MANIFEST", "statement": "Para cada archivo del paquete, el git blob sha1 calculado desde sus bytes exactos coincide con el blob declarado en source_bundle del manifiesto."}, {"code": "REFREEZE_REASON_CONSISTENT", "statement": "El motivo del refreeze (contrato A5 omitido en el primer paquete y cambio posterior del contrato de entrada de Programming y del validador Wave1) es coherente con el contenido: el paquete incluye ahora el contrato A5 (decision_context), el contrato de entrada y el validador Wave1."}, {"code": "NO_OVERCLAIM", "statement": "El manifiesto no afirma un merge realizado, ni autoriza retirar historias, ni activa runtime o producción, ni se autoconfirma (independent_confirmation_ref vacío), y declara que los gates empíricos pertenecen al primer freeze y no fueron re-ejecutados."}], "evidence_tier": "OWNER_APPROVED_GPT_NATIVE_IN_CHAT_EQUIVALENT", "files": [{"bytes": 2410, "content": "{\n  \"$schema\": \"https://json-schema.org/draft/2020-12/schema\",\n  \"$id\": \"lf/programming-agent/analysis/request-context-v1\",\n  \"title\": \"Analysis Request Context V1\",\n  \"type\": \"object\",\n  \"additionalProperties\": false,\n  \"required\": [\n    \"schema_version\",\n    \"request_identity\",\n    \"objective\",\n    \"target_hints\",\n    \"source_refs\",\n    \"provided_facts\",\n    \"constraints\",\n    \"ambiguities\",\n    \"no_solution_inferred\"\n  ],\n  \"properties\": {\n    \"schema_version\": {\"const\": \"REQUEST_CONTEXT_V1\"},\n    \"request_identity\": {\n      \"type\": \"object\",\n      \"additionalProperties\": false,\n      \"required\": [\"request_ref\", \"request_kind\"],\n      \"properties\": {\n        \"request_ref\": {\"type\": \"string\", \"minLength\": 3},\n        \"request_kind\": {\"enum\": [\"USER_REQUEST\", \"SYSTEM_REQUEST\", \"ISSUE\", \"HANDOFF\", \"FILE\", \"EVENT\", \"OTHER\"]}\n      }\n    },\n    \"objective\": {\n      \"type\": \"object\",\n      \"additionalProperties\": false,\n      \"required\": [\"problem_statement\", \"desired_outcome\"],\n      \"properties\": {\n        \"problem_statement\": {\"type\": \"string\", \"minLength\": 1},\n        \"desired_outcome\": {\"type\": \"string\", \"minLength\": 1}\n      }\n    },\n    \"target_hints\": {\"type\": \"array\", \"uniqueItems\": true, \"items\": {\"type\": \"string\", \"minLength\": 1}},\n    \"source_refs\": {\"type\": \"array\", \"uniqueItems\": true, \"items\": {\"type\": \"string\", \"minLength\": 3}},\n    \"provided_facts\": {\n      \"type\": \"array\",\n      \"items\": {\n        \"type\": \"object\",\n        \"additionalProperties\": false,\n        \"required\": [\"fact_code\", \"value\", \"source_ref\"],\n        \"properties\": {\n          \"fact_code\": {\"type\": \"string\", \"minLength\": 1},\n          \"value\": {},\n          \"source_ref\": {\"type\": \"string\", \"minLength\": 3}\n        }\n      }\n    },\n    \"constraints\": {\"type\": \"array\", \"uniqueItems\": true, \"items\": {\"type\": \"string\", \"minLength\": 1}},\n    \"ambiguities\": {\n      \"type\": \"array\",\n      \"items\": {\n        \"type\": \"object\",\n        \"additionalProperties\": false,\n        \"required\": [\"code\", \"statement\", \"materiality\", \"resolution_state\"],\n        \"properties\": {\n          \"code\": {\"type\": \"string\", \"minLength\": 1},\n          \"statement\": {\"type\": \"string\", \"minLength\": 1},\n          \"materiality\": {\"enum\": [\"MATERIAL\", \"NON_MATERIAL\", \"UNKNOWN\"]},\n          \"resolution_state\": {\"enum\": [\"OPEN\", \"RESOLVED_FROM_SOURCE\"]}\n        }\n      }\n    },\n    \"no_solution_inferred\": {\"const\": true}\n  }\n}\n", "declared_blob": "cb6cf1c663da4dc12c1f1a6fabedb6e666836d85", "path": "analysis_request_context_v1.schema.json", "unit": "A1"}, {"bytes": 5217, "content": "{\n  \"schema_version\": \"ANALYSIS_CHANGE_CLASSIFICATION_CONTRACT_V1\",\n  \"state\": 