  \"SUFFICIENT\",\n          \"INSUFFICIENT\",\n          \"UNKNOWN\"\n        ],\n        \"reversibility_state\": [\n          \"DEMONSTRATED\",\n          \"NOT_DEMONSTRATED\",\n          \"UNKNOWN\"\n        ],\n        \"currentness_decision\": [\n          \"CURRENT\",\n          \"CURRENT_REBOUND\",\n          \"STALE_AFFECTED\",\n          \"UNKNOWN_FAIL_CLOSED\",\n          \"UNRESOLVED\"\n        ],\n        \"material_contradiction\": \"BOOLEAN\",\n        \"known_cross_scope_impact\": \"BOOLEAN_OR_UNKNOWN\",\n        \"unresolved_material_signal_count\": \"NON_NEGATIVE_INTEGER\",\n        \"required_specialist_count\": \"NON_NEGATIVE_INTEGER\"\n      },\n      \"precedence\": [\n        \"L3_EXPLICIT_HIGH_RISK\",\n        \"L2_MEDIUM_OR_UNPROVEN\",\n        \"L1_FULLY_BOUNDED_LOW_RISK\"\n      ],\n      \"L3_if_any\": [\n        \"materiality_level=HIGH\",\n        \"scope_bounded=FALSE\",\n        \"authority_state=INSUFFICIENT\",\n        \"currentness_decision=STALE_AFFECTED\",\n        \"material_contradiction=true\",\n        \"known_cross_scope_impact=true\"\n      ],\n      \"L2_if_no_L3_and_any\": [\n        \"materiality_level in [MEDIUM,UNKNOWN]\",\n        \"scope_bounded=UNKNOWN\",\n        \"authority_state=UNKNOWN\",\n        \"reversibility_state in [NOT_DEMONSTRATED,UNKNOWN]\",\n        \"currentness_decision in [CURRENT_REBOUND,UNKNOWN_FAIL_CLOSED,UNRESOLVED]\",\n        \"known_cross_scope_impact=UNKNOWN\",\n        \"unresolved_material_signal_count>0\",\n        \"required_specialist_count>0\"\n      ],\n      \"L1_requires_all\": [\n        \"materiality_level=LOW\",\n        \"scope_bounded=TRUE\",\n        \"authority_state=SUFFICIENT\",\n        \"reversibility_state=DEMONSTRATED\",\n        \"currentness_decision=CURRENT\",\n        \"material_contradiction=false\",\n        \"known_cross_scope_impact=false\",\n        \"unresolved_material_signal_count=0\",\n        \"required_specialist_count=0\"\n      ],\n      \"unknown_material_never_L1\": true,\n      \"worsening_signal_cannot_reduce_depth\": true,\n      \"depth_is_execution_permission\": false,\n      \"readiness_and_admission_remain_separate\": true,\n      \"case_family_hardcoding_forbidden\": true,\n      \"arbitrary_weights_forbidden\": true\n    }\n  },\n  \"specialist_resolution\": {\n    \"output_requirements\": \"specialist_requirements[]\",\n    \"output_refs\": \"specialist_refs[]\",\n    \"cardinality\": \"0..N\",\n    \"selection_modes\": [\n      \"EXACT_ONE\",\n      \"ALL_MATCHED\"\n    ],\n    \"selector_capability\": \"CAPABILITY_SELECTOR\",\n    \"selector_version_policy\": \"CURRENT\",\n    \"currentness_required\": true,\n    \"release_state_required\": \"RELEASED\",\n    \"catalog_source\": \"CURRENT_RELEASED_CAPABILITY_MANIFESTS_WITH_SPECIALIST_DECLARATION\",\n    \"hardcoded_specialist_identity_forbidden\": true,\n    \"hardcoded_story_creator_forbidden\": true,\n    \"selection_is_execution_permission\": false,\n    \"required_no_match\": \"BLOCK_AFFECTED_SCOPE_SPECIALIST_UNRESOLVED\",\n    \"optional_no_match\": \"NOT_REQUIRED\",\n    \"contradictory_or_failure\": \"BLOCK_AFFECTED_SCOPE\"\n  },\n  \"mapped_assets\": [\n    \"CAPABILITY_SELECTOR\",\n    \"SAFE_CHANGE_ADMISSION\",\n    \"SOURCE_RESOLUTION_POLICY\",\n    \"CURRENTNESS_AUTHORITY\"\n  ],\n  \"no_parallel_engine\": true,\n  \"source_refs\": [\n    \"lf_eventos://20333\",\n    \"lf_eventos://20334\",\n    \"ekb://PROGRAMMING-ANALYSIS-DEPTH-POLICY-UNDEFINED-001\",\n    \"capability://SAFE_CHANGE_ADMISSION@1.0.1\",\n    \"capability://CURRENTNESS_AUTHORITY@1.0.0\"\n  ]\n}", "declared_blob": "0f07d3603c1bf3e4d2a4b9de5d6c3a3968bb4051", "path": "analysis_change_classification_contract_v1.json", "unit": "A2"}, {"bytes": 3203, "content": "{\n  \"schema_version\": \"ANALYSIS_TARGETED_EVIDENCE_CONTRACT_V1\",\n  \"state\": \"SOURCE_ONLY_CANDIDATE\",\n  \"unit\": \"A3\",\n  \"input_contracts\": [\"REQUEST_CONTEXT_V1\",\"ANALYSIS_CHANGE_CLASSIFICATION_V1\"],\n  \"output_contract\": \"TARGETED_EVIDENCE_SET_V1\",\n  \"acquisition\": {\n    \"capability\": \"TARGETED_EVIDENCE_ACQUISITION\",\n    \"source_resolution\": \"SOURCE_RESOLUTION_POLICY\",\n    \"data_access\": \"TYPED_DATA_ACCESS\",\n    \"query_only_missing_or_material_evidence\": true,\n    \"reuse_current_evidence_before_fetch\": true,\n    \"duplicate_read_forbidden\": true,\n    \"full_repository_search_without_trigger_forbidden\": true,\n    \"stop_when\": \"MINIMUM_SUFFICIENT_CONTEXT_REACHED\",\n    \"continue_only_if\": [\"REQUIRED_EVIDENCE_MISSING\",\"MATERIAL_CONTRADICTION\",\"CURRENTNESS_UNPROVEN\",\"SOURCE_DRIFT\"],\n    \"blocked_if\": [\"REQUIRED_SOURCE_UNAVAILABLE\",\"MATERIAL_AMBIGUITY_REQUIRES_DECISION\"]\n  },\n  \"target_resolution\": {\n    \"required_when_target_hints_present\": true,\n    \"target_granularity_required\": true,\n    \"resolver_order\": [\"EXACT_TARGET_IDENTITY\",\"CURRENT_CANONICAL_AUTHORITY\",\"CURRENT_IMPLEMENTATION\",\"RELATED_AUTHORITIES\",\"CONSUMERS_AND_DEPENDENCIES\"],\n    \"state_dimensions\": {\n      \"authority_state\": [\"EXISTING\",\"NEW\",\"UNKNOWN\"],\n      \"implementation_state\": [\"EXISTING\",\"NEW\",\"UNKNOWN\"]\n    },\n    \"authority_existing_requires\": [\"exact_target_ref\",\"authority_currentness_ref\",\"authority_refs[]\"],\n    \"authority_new_requires\": [\"negative_canonical_authority_evidence[]\",\"canonical_search_scope[]\",\"new_authority_reason\"],\n    \"implementation_existing_requires\": [\"implementation_refs[]\",\"implementation_currentness_refs[]\",\"as_is_consumers[]\",\"as_is_dependencies[]\",\"explicit_delta\"],\n    \"implementation_new_requires\": [\"negative_current_implementation_evidence[]\",\"reuse_search_scope[]\",\"reuse_candidates_evaluated[]\",\"authority_refs_or_explicit_gaps[]\"],\n    \"authority_existing_implementation_new_allowed\": true,\n    \"authority_state_does_not_imply_implementation_state\": true,\n    \"implementation_existing_greenfield_redefinition_forbidde